// Get first incoming item safely
const item = $input.first();

// Safely extract content (prevents undefined errors)
const content = item.json?.output?.[0]?.content?.[0]?.text || "No content generated.";

// Add header & footer branding dynamically
const formattedMessage = `
*📰 AI INSIDER DAILY*
_Your automated AI intelligence brief_

${content}

---
🤖 Automated via n8n AI Workflow
`;

// Return formatted message
return [
  {
    json: {
      message: formattedMessage
    }
  }
];
